import os
import sys
import csv
import json
import itertools
import math
import time
from collections import defaultdict

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"

# ---------------- Load data ----------------
def load_data():
    cases = []
    with open(os.path.join(DATA, "cases.csv")) as f:
        for row in csv.DictReader(f):
            cases.append({
                "case_id": row["case_id"],
                "item_id": int(row["item_id"]),
                "length": float(row["length"]),
                "width": float(row["width"]),
                "height": float(row["height"]),
                "weight": float(row["weight"]),
            })
    bins = []
    with open(os.path.join(DATA, "bins.csv")) as f:
        for row in csv.DictReader(f):
            bins.append({
                "bin_id": row["bin_id"],
                "length": float(row["length"]),
                "width": float(row["width"]),
                "height": float(row["height"]),
                "max_weight": float(row["max_weight"]),
                "com_tx": float(row["center_of_mass_target_x"]),
                "com_ty": float(row["center_of_mass_target_y"]),
            })
    items = {}
    with open(os.path.join(DATA, "items.csv")) as f:
        for row in csv.DictReader(f):
            items[int(row["item_id"])] = {
                "quantity": int(row["quantity"]),
                "length": float(row["length"]),
                "width": float(row["width"]),
                "height": float(row["height"]),
                "weight": float(row["weight"]),
            }
    affinities = []
    with open(os.path.join(DATA, "affinities.csv")) as f:
        for row in csv.DictReader(f):
            affinities.append({
                "rule_id": row["rule_id"],
                "rule_type": row["rule_type"],
                "a": int(row["item_id_a"]),
                "b": int(row["item_id_b"]),
            })
    relpos = []
    with open(os.path.join(DATA, "relative_positions.csv")) as f:
        for row in csv.DictReader(f):
            relpos.append({
                "relation": row["relation"],
                "first": int(row["first_item_id"]),
                "second": int(row["second_item_id"]),
            })
    handling = {}
    with open(os.path.join(DATA, "handling_rules.csv")) as f:
        for row in csv.DictReader(f):
            handling[int(row["item_id"])] = {
                "fragile": int(row["fragile"]),
                "max_stack_load": float(row["max_stack_load"]),
                "min_support_coverage": float(row["min_support_coverage"]),
            }
    stops = {}
    with open(os.path.join(DATA, "delivery_stops.csv")) as f:
        for row in csv.DictReader(f):
            stops[row["stop_id"]] = int(row["unload_sequence"])
    dest = {}
    with open(os.path.join(DATA, "case_destinations.csv")) as f:
        for row in csv.DictReader(f):
            dest[row["case_id"]] = row["stop_id"]
    with open(os.path.join(DATA, "config.json")) as f:
        config = json.load(f)
    return cases, bins, items, affinities, relpos, handling, stops, dest, config

def orientations(dims):
    l, w, h = dims
    seen = set()
    out = []
    for perm in itertools.permutations([l, w, h]):
        if perm not in seen:
            seen.add(perm)
            out.append(perm)
    return out

# ---------------- Geometry helpers ----------------
def overlap_3d(a, b):
    ox = min(a[0] + a[3], b[0] + b[3]) - max(a[0], b[0])
    oy = min(a[1] + a[4], b[1] + b[4]) - max(a[1], b[1])
    oz = min(a[2] + a[5], b[2] + b[5]) - max(a[2], b[2])
    if ox <= 1e-9 or oy <= 1e-9 or oz <= 1e-9:
        return False
    return True

def union_area(rects):
    if not rects:
        return 0.0
    events = []
    for (x1, y1, x2, y2) in rects:
        events.append((y1, 1, x1, x2))
        events.append((y2, -1, x1, x2))
    events.sort(key=lambda e: (e[0], e[1]))
    active = []
    total = 0.0
    last_y = events[0][0]
    for (y, typ, x1, x2) in events:
        if y > last_y:
            active_sorted = sorted(active)
            cov = 0.0
            cur_start = None
            cur_end = None
            for (a, b) in active_sorted:
                if cur_start is None:
                    cur_start, cur_end = a, b
                elif a <= cur_end + 1e-9:
                    cur_end = max(cur_end, b)
                else:
                    cov += cur_end - cur_start
                    cur_start, cur_end = a, b
            if cur_start is not None:
                cov += cur_end - cur_start
            total += cov * (y - last_y)
        if typ == 1:
            active.append((x1, x2))
        else:
            try:
                active.remove((x1, x2))
            except ValueError:
                pass
        last_y = y
    return total

# ---------------- Packing heuristic ----------------
def try_pack(bin_cases, bin, handling, relpos, stops, dest):
    L, W, H = bin["length"], bin["width"], bin["height"]
    # Sort cases: heavy/lower first (items 0,7 first), then by volume desc
    def sort_key(c):
        item = c["item_id"]
        base = 0 if item in (0, 7) else 1
        return (base, -c["length"] * c["width"] * c["height"])
    cases_sorted = sorted(bin_cases, key=sort_key)

    placed_boxes = []  # [x, y, z, xs, ys, zs, top, item_id, case_id, load]

    def footprint_support(x, y, z, xs, ys, placed_boxes):
        cx, cy, cx2, cy2 = x, y, x + xs, y + ys
        cz = z
        covered = 0.0
        rects = []
        for pb in placed_boxes:
            if pb[4] + pb[6] <= cz + 1e-9:  # pb top <= cand bottom
                ox = min(cx2, pb[0] + pb[2]) - max(cx, pb[0])
                oy = min(cy2, pb[1] + pb[3]) - max(cy, pb[1])
                if ox > 1e-9 and oy > 1e-9:
                    rects.append((max(cx, pb[0]), max(cy, pb[1]), min(cx2, pb[0] + pb[2]), min(cy2, pb[1] + pb[3])))
        if not rects:
            return 0.0
        return union_area(rects)

    def candidates_for(xs, ys, zs, placed_boxes):
        xs_set = {0.0}
        ys_set = {0.0}
        zs_set = {0.0}
        for pb in placed_boxes:
            for base in (pb[0] + pb[2], pb[0] - xs):
                xs_set.add(base)
            for base in (pb[1] + pb[3], pb[1] - ys):
                ys_set.add(base)
            for base in (pb[4] + pb[6]):
                zs_set.add(base)
        cands = []
        for x in xs_set:
            for y in ys_set:
                for z in zs_set:
                    if x < -1e-9 or y < -1e-9 or z < -1e-9:
                        continue
                    if x + xs > L + 1e-9 or y + ys > W + 1e-9 or z + zs > H + 1e-9:
                        continue
                    cands.append((x, y, z))
        # sort by z, then y (door at high y: prefer high y for earlier stops)
        cands.sort(key=lambda c: (c[2], -c[1], c[0]))
        return cands

    def check_nonoverlap(x, y, z, xs, ys, zs, placed_boxes):
        for pb in placed_boxes:
            if overlap_3d((x, y, z, xs, ys, zs), pb):
                return False
        return True

    def check_above_rules(x, y, z, xs, ys, zs, item, placed_boxes, relpos):
        for pb in placed_boxes:
            ij = pb[7]
            for rp in relpos:
                if rp["relation"] != "above":
                    continue
                if rp["first"] == item and rp["second"] == ij:
                    if z < pb[4] + pb[6] - 1e-9:
                        return False
                if rp["first"] == ij and rp["second"] == item:
                    if pb[4] < z + zs - 1e-9:
                        return False
        return True

    def check_unloading(x, y, z, ys, zs, item, case_id, stop_seq, placed_boxes, stops, dest):
        for pb in placed_boxes:
            jid = pb[8]
            sj = stops[dest[jid]]
            if sj == stop_seq:
                continue
            ox = min(x + xs, pb[0] + pb[2]) - max(x, pb[0])
            oz = min(z + zs, pb[4] + pb[6]) - max(z, pb[4])
            if ox <= 1e-9 or oz <= 1e-9:
                continue
            if stop_seq < sj:
                if y + ys < pb[1] - 1e-9:
                    return False
            else:
                if pb[1] + pb[3] < y - 1e-9:
                    return False
        return True

    def check_support(x, y, z, xs, ys, placed_boxes, mincov):
        if z <= 1e-9:
            return True
        area = footprint_support(x, y, z, xs, ys, placed_boxes)
        return area >= mincov * xs * ys - 1e-9

    def check_crush(x, y, z, xs, ys, zs, weight, item, placed_boxes, handling):
        for pb in placed_boxes:
            if pb[4] + pb[6] > z + 1e-9:
                continue
            ox = min(x + xs, pb[0] + pb[2]) - max(x, pb[0])
            oy = min(y + ys, pb[1] + pb[3]) - max(y, pb[1])
            if ox <= 1e-9 or oy <= 1e-9:
                continue
            h = handling[pb[7]]
            if h["fragile"]:
                return False
            if pb[9] + weight > h["max_stack_load"] + 1e-9:
                return False
        return True

    def update_loads(x, y, z, xs, ys, weight, placed_boxes):
        for pb in placed_boxes:
            if pb[4] + pb[6] > z + 1e-9:
                continue
            ox = min(x + xs, pb[0] + pb[2]) - max(x, pb[0])
            oy = min(y + ys, pb[1] + pb[3]) - max(y, pb[1])
            if ox > 1e-9 and oy > 1e-9:
                pb[9] += weight

    def undo_loads(x, y, z, xs, ys, weight, placed_boxes):
        for pb in placed_boxes:
            if pb[4] + pb[6] > z + 1e-9:
                continue
            ox = min(x + xs, pb[0] + pb[2]) - max(x, pb[0])
            oy = min(y + ys, pb[1] + pb[3]) - max(y, pb[1])
            if ox > 1e-9 and oy > 1e-9:
                pb[9] -= weight

    def backtrack(idx):
        if idx == len(cases_sorted):
            return True
        c = cases_sorted[idx]
        item = c["item_id"]
        stop_seq = stops[dest[c["case_id"]]]
        mincov = handling[item]["min_support_coverage"]
        dims = (c["length"], c["width"], c["height"])
        for (xs, ys, zs) in orientations(dims):
            cands = candidates_for(xs, ys, zs, placed_boxes)
            for (x, y, z) in cands:
                if not check_nonoverlap(x, y, z, xs, ys, zs, placed_boxes):
                    continue
                if not check_above_rules(x, y, z, xs, ys, zs, item, placed_boxes, relpos):
                    continue
                if not check_unloading(x, y, z, ys, zs, item, c["case_id"], stop_seq, placed_boxes, stops, dest):
                    continue
                if not check_support(x, y, z, xs, ys, placed_boxes, mincov):
                    continue
                if not check_crush(x, y, z, xs, ys, zs, c["weight"], item, placed_boxes, handling):
                    continue
                pb = [x, y, z, xs, ys, zs, z + zs, item, c["case_id"], 0.0]
                placed_boxes.append(pb)
                update_loads(x, y, z, xs, ys, c["weight"], placed_boxes)
                if backtrack(idx + 1):
                    return True
                placed_boxes.pop()
                undo_loads(x, y, z, xs, ys, c["weight"], placed_boxes)
        return False

    if not backtrack(0):
        return None

    result = {}
    for pb in placed_boxes:
        result[pb[8]] = (pb[0], pb[1], pb[2], pb[3], pb[4], pb[5])
    return result

# ---------------- Validation ----------------
def validate_solution(sol, cases, bins, handling, relpos, stops, dest, affinities):
    tol = 1e-6
    bin_map = {b["bin_id"]: b for b in bins}
    by_bin = defaultdict(list)
    for cid, (bid, x, y, z, xs, ys, zs) in sol.items():
        by_bin[bid].append((cid, x, y, z, xs, ys, zs))
    case_map = {c["case_id"]: c for c in cases}
    for bid, lst in by_bin.items():
        b = bin_map[bid]
        L, W, H = b["length"], b["width"], b["height"]
        total_w = 0.0
        for (cid, x, y, z, xs, ys, zs) in lst:
            c = case_map[cid]
            total_w += c["weight"]
            if x < -tol or y < -tol or z < -tol:
                return False, f"{cid} negative coord"
            if x + xs > L + tol or y + ys > W + tol or z + zs > H + tol:
                return False, f"{cid} out of bin"
            orig = (c["length"], c["width"], c["height"])
            allowed = set(orientations(orig))
            if (xs, ys, zs) not in allowed:
                return False, f"{cid} bad orientation"
        if total_w > b["max_weight"] + tol:
            return False, f"bin {bid} overweight"
        for i in range(len(lst)):
            for j in range(i + 1, len(lst)):
                c1 = lst[i]
                c2 = lst[j]
                if overlap_3d((c1[1], c1[2], c1[3], c1[4], c1[5], c1[6]),
                              (c2[1], c2[2], c2[3], c2[4], c2[5], c2[6])):
                    return False, f"overlap {c1[0]} {c2[0]}"
                i1 = case_map[c1[0]]["item_id"]
                i2 = case_map[c2[0]]["item_id"]
                for rp in relpos:
                    if rp["relation"] != "above":
                        continue
                    if rp["first"] == i1 and rp["second"] == i2:
                        if c1[3] < c2[3] + c2[6] - tol:
                            return False, f"above rule {c1[0]} {c2[0]}"
                    if rp["first"] == i2 and rp["second"] == i1:
                        if c2[3] < c1[3] + c1[6] - tol:
                            return False, f"above rule {c2[0]} {c1[0]}"
                s1 = stops[dest[c1[0]]]
                s2 = stops[dest[c2[0]]]
                if s1 != s2:
                    ox = min(c1[1] + c1[4], c2[1] + c2[4]) - max(c1[1], c2[1])
                    oz = min(c1[3] + c1[6], c2[3] + c2[6]) - max(c1[3], c2[3])
                    if ox > tol and oz > tol:
                        if s1 < s2:
                            if c1[2] + c1[5] < c2[2] - tol:
                                return False, f"unloading {c1[0]} {c2[0]}"
                        else:
                            if c2[2] + c2[5] < c1[2] - tol:
                                return False, f"unloading {c2[0]} {c1[0]}"
        for (cid, x, y, z, xs, ys, zs) in lst:
            c = case_map[cid]
            item = c["item_id"]
            mincov = handling[item]["min_support_coverage"]
            if z > tol:
                covered = 0.0
                rects = []
                for (cid2, x2, y2, z2, xs2, ys2, zs2) in lst:
                    if cid2 == cid:
                        continue
                    if z2 + zs2 <= z + tol:
                        ox = min(x + xs, x2 + xs2) - max(x, x2)
                        oy = min(y + ys, y2 + ys2) - max(y, y2)
                        if ox > tol and oy > tol:
                            rects.append((max(x, x2), max(y, y2), min(x + xs, x2 + xs2), min(y + ys, y2 + ys2)))
                covered = union_area(rects)
                if covered < mincov * xs * ys - tol:
                    return False, f"support {cid}"
            load = 0.0
            for (cid2, x2, y2, z2, xs2, ys2, zs2) in lst:
                if cid2 == cid:
                    continue
                if z2 >= z + zs - tol:
                    ox = min(x + xs, x2 + xs2) - max(x, x2)
                    oy = min(y + ys, y2 + ys2) - max(y, y2)
                    if ox > tol and oy > tol:
                        load += case_map[cid2]["weight"]
            h = handling[item]
            if h["fragile"]:
                if load > tol:
                    return False, f"crush fragile {cid}"
            else:
                if load > h["max_stack_load"] + tol:
                    return False, f"crush {cid}"
    bin_of_item = defaultdict(set)
    for cid, (bid, x, y, z, xs, ys, zs) in sol.items():
        item = case_map[cid]["item_id"]
        bin_of_item[item].add(bid)
    for af in affinities:
        if af["rule_type"] == "positive":
            if bin_of_item[af["a"]] != bin_of_item[af["b"]]:
                return False, f"affinity {af['rule_id']}"
        else:
            if bin_of_item[af["a"]] & bin_of_item[af["b"]]:
                return False, f"incompatible {af['rule_id']}"
    return True, "ok"

# ---------------- Score ----------------
def score_solution(sol, cases, bins):
    case_map = {c["case_id"]: c for c in cases}
    bin_map = {b["bin_id"]: b for b in bins}
    used_bins = set()
    max_h = {}
    com = {}
    for cid, (bid, x, y, z, xs, ys, zs) in sol.items():
        used_bins.add(bid)
        top = z + zs
        if bid not in max_h or top > max_h[bid]:
            max_h[bid] = top
        if bid not in com:
            com[bid] = [0.0, 0.0, 0.0]
        w = case_map[cid]["weight"]
        com[bid][0] += w * (x + xs / 2)
        com[bid][1] += w * (y + ys / 2)
        com[bid][2] += w
    total_h = sum(max_h.values())
    avg_top = sum(v[2] + v[5] for v in sol.values()) / len(sol)
    com_l1 = 0.0
    for bid in used_bins:
        b = bin_map[bid]
        wx, wy, wtot = com[bid]
        cx = wx / wtot
        cy = wy / wtot
        com_l1 += abs(cx - b["com_tx"]) + abs(cy - b["com_ty"])
    obj = 1e6 * len(used_bins) + 1.0 * total_h + 1.0 * avg_top + 0.01 * com_l1
    return obj

def used_bins_set(sol):
    return set(v[0] for v in sol.values())

# ---------------- SCIP MIP (simplified) ----------------
def run_scip_mip(cases, bins, items, affinities, relpos, handling, stops, dest, config, time_limit):
    try:
        from pyscipopt import Model, quicksum
    except ImportError:
        print("PySCIPOpt not available, skipping MIP.")
        return None

    model = Model("3d_bin_packing")
    model.setParam("gaprel", 0.0005)
    model.setParam("limits/time", time_limit)

    n_cases = len(cases)
    n_bins = len(bins)
    case_ids = [c["case_id"] for c in cases]
    bin_ids = [b["bin_id"] for b in bins]

    # Variables
    b = {}  # b[(i,k)] = 1 if case i in bin k
    o = {}  # o[(i,r)] = 1 if case i uses orientation r
    x = {}  # x[i] = x coordinate
    y = {}  # y[i] = y coordinate
    z = {}  # z[i] = z coordinate

    for i, c in enumerate(cases):
        for k, bid in enumerate(bin_ids):
            b[(i, k)] = model.addVar(name=f"b_{i}_{k}", vtype="B", lb=0, ub=1, obj=0.0)
        for r, (xs, ys, zs) in enumerate(orientations((c["length"], c["width"], c["height"]))):
            o[(i, r)] = model.addVar(name=f"o_{i}_{r}", vtype="B", lb=0, ub=1, obj=0.0)
        x[i] = model.addVar(name=f"x_{i}", vtype="C", lb=0, ub=bins[0]["length"], obj=0.0)
        y[i] = model.addVar(name=f"y_{i}", vtype="C", lb=0, ub=bins[0]["width"], obj=0.0)
        z[i] = model.addVar(name=f"z_{i}", vtype="C", lb=0, ub=bins[0]["height"], obj=0.0)

    # Assignment constraints
    for i in range(n_cases):
        model.addCons(quicksum(b[(i, k)] for k in range(n_bins)) == 1, name=f"assign_{i}")

    # Orientation constraints
    for i, c in enumerate(cases):
        ors = orientations((c["length"], c["width"], c["height"]))
        model.addCons(quicksum(o[(i, r)] for r in range(len(ors))) == 1, name=f"orient_{i}")

    # Size variables (simplified: use max possible size for bounds)
    # For non-overlap, we need actual sizes. Use big-M with orientation-dependent sizes.
    # This is complex; skip full MIP for now and rely on heuristic.
    # Instead, just set objective for used bins and let heuristic handle geometry.

    # Weight constraints
    for k, bid in enumerate(bin_ids):
        model.addCons(quicksum(c["weight"] * b[(i, k)] for i, c in enumerate(cases)) <= bins[k]["max_weight"], name=f"weight_{k}")

    # Affinity constraints
    case_map = {c["case_id"]: c for c in cases}
    item_to_cases = defaultdict(list)
    for i, c in enumerate(cases):
        item_to_cases[c["item_id"]].append(i)

    for af in affinities:
        if af["rule_type"] == "positive":
            for i in item_to_cases[af["a"]]:
                for j in item_to_cases[af["b"]]:
                    for k in range(n_bins):
                        model.addCons(b[(i, k)] == b[(j, k)], name=f"aff_{af['rule_id']}_{i}_{j}_{k}")
        else:
            for i in item_to_cases[af["a"]]:
                for j in item_to_cases[af["b"]]:
                    for k in range(n_bins):
                        model.addCons(b[(i, k)] + b[(j, k)] <= 1, name=f"sep_{af['rule_id']}_{i}_{j}_{k}")

    # Objective: minimize used bins
    used = {}
    for k in range(n_bins):
        used[k] = model.addVar(name=f"used_{k}", vtype="B", lb=0, ub=1, obj=1e6)
        for i in range(n_cases):
            model.addCons(b[(i, k)] <= used[k], name=f"use_link_{i}_{k}")

    model.setObjective(quicksum(used[k] for k in range(n_bins)), sense="minimize")

    print("Solving MIP...")
    model.optimize()
    status = model.getStatus()
    print(f"MIP status: {status}")

    if status not in ("optimal", "bestsollimit", "timelimit", "gap"):
        print("MIP did not find a good solution.")
        return None

    sol = model.getBestSol()
    if sol is None:
        return None

    result = {}
    for i, c in enumerate(cases):
        # Find bin
        bid = None
        for k in range(n_bins):
            if model.getVal(b[(i, k)]) > 0.5:
                bid = bin_ids[k]
                break
        if bid is None:
            return None

        # Find orientation
        ors = orientations((c["length"], c["width"], c["height"]))
        xs, ys, zs = ors[0]
        for r in range(len(ors)):
            if model.getVal(o[(i, r)]) > 0.5:
                xs, ys, zs = ors[r]
                break

        xi = model.getVal(x[i])
        yi = model.getVal(y[i])
        zi = model.getVal(z[i])

        result[c["case_id"]] = (bid, xi, yi, zi, xs, ys, zs)

    return result

# ---------------- Main ----------------
def main():
    cases, bins, items, affinities, relpos, handling, stops, dest, config = load_data()
    case_map = {c["case_id"]: c for c in cases}
    bin_map = {b["bin_id"]: b for b in bins}

    # Determine item groups
    items_list = sorted(set(c["item_id"] for c in cases))
    group_a = {0, 3, 8}
    free_items = [i for i in items_list if i not in group_a and i not in (7, 9)]

    best_sol = None
    best_score = float("inf")

    # Enumerate assignments
    for ga_bin in [0, 1]:
        for i7_bin in [0, 1]:
            i9_bin = 1 - i7_bin
            for free_assign in itertools.product([0, 1], repeat=len(free_items)):
                item_bin = {}
                for i in group_a:
                    item_bin[i] = ga_bin
                item_bin[7] = i7_bin
                item_bin[9] = i9_bin
                for i, b in zip(free_items, free_assign):
                    item_bin[i] = b
                # weight check
                weights = [0.0, 0.0]
                for c in cases:
                    weights[item_bin[c["item_id"]]] += c["weight"]
                if weights[0] > bins[0]["max_weight"] + 1e-9 or weights[1] > bins[1]["max_weight"] + 1e-9:
                    continue
                # pack
                bin_cases = {0: [], 1: []}
                for c in cases:
                    bin_cases[item_bin[c["item_id"]]].append(c)
                sol = {}
                ok = True
                for bid in [0, 1]:
                    if not bin_cases[bid]:
                        continue
                    res = try_pack(bin_cases[bid], bins[bid], handling, relpos, stops, dest)
                    if res is None:
                        ok = False
                        break
                    for cid, (x, y, z, xs, ys, zs) in res.items():
                        sol[cid] = (bins[bid]["bin_id"], x, y, z, xs, ys, zs)
                if not ok:
                    continue
                valid, msg = validate_solution(sol, cases, bins, handling, relpos, stops, dest, affinities)
                if not valid:
                    continue
                sc = score_solution(sol, cases, bins)
                if sc < best_score:
                    best_score = sc
                    best_sol = sol

    if best_sol is None:
        print("No feasible solution found by heuristic; trying SCIP MIP...")
        # Try MIP as fallback
        time_limit = 300.0
        env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
        if env_limit is not None:
            try:
                time_limit = min(time_limit, float(env_limit))
            except ValueError:
                pass
        mip_sol = run_scip_mip(cases, bins, items, affinities, relpos, handling, stops, dest, config, time_limit)
        if mip_sol is not None:
            valid, msg = validate_solution(mip_sol, cases, bins, handling, relpos, stops, dest, affinities)
            if valid:
                best_sol = mip_sol
                best_score = score_solution(best_sol, cases, bins)
                print(f"MIP solution valid, score: {best_score}")
            else:
                print(f"MIP solution invalid: {msg}")

    if best_sol is None:
        print("No feasible solution found. Writing empty solution.")
        best_sol = {}

    # Write solution
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["case_id", "item_id", "bin_id", "x", "y", "z", "x_size", "y_size", "z_size"])
        for c in cases:
            cid = c["case_id"]
            if cid in best_sol:
                bid, x, y, z, xs, ys, zs = best_sol[cid]
                w.writerow([cid, c["item_id"], bid, f"{x:.8f}", f"{y:.8f}", f"{z:.8f}", f"{xs:.8f}", f"{ys:.8f}", f"{zs:.8f}"])
            else:
                w.writerow([cid, c["item_id"], "B0", "0", "0", "0", str(c["length"]), str(c["width"]), str(c["height"])])

    print(f"Best score: {best_score}")
    if best_sol:
        valid, msg = validate_solution(best_sol, cases, bins, handling, relpos, stops, dest, affinities)
        print(f"Validation: {valid} {msg}")
    else:
        print("No solution to validate.")

if __name__ == "__main__":
    main()
